import React from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

/**
 * Error UI Component for displaying error information
 */
const ErrorUI = ({ error, resetErrorBoundary }) => {
  const { theme } = useTheme();
  
  return (
    <motion.div
      className={`min-h-screen flex items-center justify-center p-5 ${theme.isDark ? 'bg-gray-900' : 'bg-gray-50'}`}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.4 }}
    >
      <div className={`max-w-md w-full ${theme.card} rounded-xl shadow-xl p-6 relative overflow-hidden`}>
        <div className="absolute inset-0 opacity-50 bg-gradient-to-br from-red-500/20 via-red-500/10 to-transparent"></div>
        
        <div className="relative z-10">
          <div className="w-16 h-16 mx-auto mb-4 bg-red-100 rounded-full flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
          </div>
          
          <h2 className={`text-xl font-bold ${theme.text.primary} text-center mb-2`}>
            Something went wrong
          </h2>
          
          <p className={`${theme.text.secondary} text-center mb-6`}>
            We apologize for the inconvenience. The application has encountered an unexpected error.
          </p>
          
          <div className={`p-3 rounded-lg ${theme.isDark ? 'bg-gray-800' : 'bg-gray-100'} mb-6 overflow-auto max-h-32`}>
            <p className="text-red-500 text-sm font-mono">{error.message}</p>
          </div>
          
          <div className="flex flex-col space-y-3">
            <motion.button
              onClick={resetErrorBoundary}
              className={`w-full py-2.5 px-4 rounded-lg ${theme.button.primary} text-white font-medium shadow-sm`}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              Try Again
            </motion.button>
            
            <motion.button
              onClick={() => window.location.href = '/'}
              className={`w-full py-2.5 px-4 rounded-lg ${theme.button.secondary} font-medium`}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              Back to Dashboard
            </motion.button>
          </div>
        </div>
      </div>
    </motion.div>
  );
};

/**
 * Error Boundary class component for catching and handling runtime errors
 */
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { 
      hasError: false,
      error: null
    };
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render will show the fallback UI
    return { 
      hasError: true,
      error
    };
  }

  componentDidCatch(error, errorInfo) {
    // Log error information for debugging
    console.error('Error caught by ErrorBoundary:', error);
    console.error('Component stack:', errorInfo.componentStack);
    
    // Could also send to error reporting service
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  }

  resetErrorBoundary = () => {
    this.setState({ 
      hasError: false,
      error: null
    });
    
    // Call the onReset prop if provided
    if (this.props.onReset) {
      this.props.onReset();
    }
  }

  render() {
    if (this.state.hasError) {
      // Render the error UI
      return (
        <ErrorUI 
          error={this.state.error}
          resetErrorBoundary={this.resetErrorBoundary}
        />
      );
    }

    // Otherwise, render children normally
    return this.props.children;
  }
}

export default ErrorBoundary; 